return {
  ["potactics-tallon-zek"] = {overview = {"Tallon Zek teleports around his chamber and repeatedly switches targets."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Expect a shadowstep every six to eighteen seconds. Reposition without scattering the group outside the chamber.", "His hate changes favor a player at 30% health or lower when one is available. Keep injured players topped up and tank pickups ready.", "Players close to Tallon can trigger Avatar Power, an area knockback on a twenty-second cycle after the opening check.", "After victory, hail the planar projection promptly; it remains for ten minutes."}}}},
  ["potactics-vallon-zek"] = {overview = {"Identify the real Vallon Zek through five rounds of copies, then defeat his final form."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Before the final round, pushing the real Vallon to 61% health makes him vanish and summons five figures: one real Vallon and four copies.", "Control the copies while locating the real target. Repeat the 61% transition through five split rounds.", "The real Vallon in the fifth replacement group can be killed normally. Defeat him and approach the resulting planar projection.", "An unengaged event can reset after twenty minutes, removing the copies."}}}},
  ["dulak-quigli"] = {overview = {"Quigli calls his crew when a monk accepts the challenge."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible monk can choose the crew fight through dialogue.", "The first crew arrives five seconds after the challenge begins.", "Collect the lackey, swabbies and scallywag while keeping pressure on Quigli.", "Finish inside the fifteen-minute encounter window."}}}},
  ["eastkarana-althele-s-druid-gathering-defense"] = {overview = {"Protect Althele's druid gathering from the incoming dark elves."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Complete the gathering sequence before preparing for the attack.", "About a minute after the ritual starts, a corruptor and two reavers advance toward Althele.", "Intercept the attackers before they reach the druids.", "Complete the quest follow-up before the gathering resets."}}}},
  ["eastwastes-boridain-glacierbane-escort-coldain-ring2"] = {overview = {"Protect Boridain on his hunt and defeat the rabid kodiak at the end."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The quest hand-in starts Boridain's route.", "Stay with him through his food and rest stops.", "At the final stop, defeat the rabid tundra kodiak and return the requested proof to Boridain."}}}},
  ["eastwastes-corbin-blackwell-rescue-coldain-ring7"] = {overview = {"Free Corbin and escort him through the orc and giant ambushes."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare before the rescue hand-in starts the moving escort.", "The first ambush brings Ry'Gorr bashers directly onto the route.", "The second brings Commander Bahreck and Kromrif soldiers. Stay close enough to protect Corbin.", "Keep him alive until he reaches the final escape point."}}}},
  ["eastwastes-icefang-poxbreath-pursuit-coldain-ring6"] = {overview = {"Follow Icefang to Poxbreath and defeat the orc party."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep up when Icefang follows the scent.", "Prepare for Poxbreath and nearby oracles at the destination.", "Finish the confrontation promptly before Icefang's reset removes the event."}}}},
  ["eastwastes-peffin-ambersnow-berradin-confrontation"] = {overview = {"Expose Peffin's protection and follow the confrontation through Berradin."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have combat support ready before the quest exchange with Peffin.", "Peffin's confrontation brings Kromrif elites; collect them before focusing the main target.", "Complete Berradin's dialogue sequence and prepare for the replacement encounter form."}}}},
  ["eastwastes-ry-gorr-assault-chief-ry-gorr-coldain-ring8"] = {overview = {"Escort Garadain into battle, defeat Chief Ry'Gorr and bring him home alive."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Complete the marching-order hand-in only when the force is assembled.", "Stay with Garadain as he gathers the Coldain and moves to the battlefield.", "Prioritize protecting Garadain and defeating the chief amid the larger battle.", "Return the required proof while the battle version of Garadain remains alive."}}}},
  ["eastwastes-scarbrow-ga-hruk-assault-coldain-ring5"] = {overview = {"Defend the Coldain camp against Scarbrow and his invading orcs."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The messenger-order hand-in to the lookout starts the assault.", "Prepare to collect Scarbrow, invaders and oracles together.", "Defeat Scarbrow and retain the required quest proof for Garadain."}}}},
  ["eastwastes-tain-hammerfrost-defense-coldain-ring4"] = {overview = {"Save the wounded Tain from Ghrek and the pursuing giants."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare before telling Tain you will help.", "Intercept Ghrek and four soldiers as they advance directly on Tain.", "Defeat the leader and deliver the requested elixir to finish the rescue."}}}},
  ["poair-chamberlain-escalardian"] = {overview = {"Defeat the island’s castellans and constables to summon Chamberlain Escalardian."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The fifth, tenth and fifteenth qualifying castellan kills summon a constable. Defeat all three constables to reach the final opponent.", "Escalardian periodically clears his hate list. Tanks should be ready to reclaim him while damage dealers avoid an uncontrolled burst.", "If the main encounter is already on cooldown, an apprentice appears instead.", "The island event has a three-hour failure timer."}}}},
  ["poair-elemental-masterpiece"] = {overview = {"Clear the confused elementals, defeat four champions and confront the Elemental Masterpiece."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The sixth, eleventh, sixteenth and twenty-first qualifying elemental kills bring out champions. The last required elemental’s death activates the champions.", "Defeat all four champions to summon the Masterpiece or its cooldown replacement, an Elemental Anomaly.", "The Masterpiece has a chance to clear hate every twelve seconds. Keep a tank ready to re-establish control.", "Victory can summon the Avatar of Smoke when that progression stage is available. The island sequence must finish within three hours."}}}},
  ["poair-melernil-faal-armanna"] = {overview = {"Clear the phoenix island, then defeat firesurgers, windsurgers and Melernil Faal’Armanna."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear all twenty designated island creatures to summon four phoenix firesurgers.", "Defeat the four firesurgers to summon four windsurgers. Defeat those to bring out Melernil or the cooldown replacement.", "Melernil may clear hate every twelve seconds. Prepare tanks to regain control throughout the final fight.", "Victory can summon the Avatar of Mist. The event has a three-hour failure timer."}}}},
  ["poair-sigismond-windwalker"] = {overview = {"Defeat the spider island’s inhabitants and archwalkers to expose Sigismond Windwalker."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear all thirty-eight designated island spawns. Sigismond grows as the required kill count advances.", "Defeat three archwalkers. The first two deaths produce smaller vorladien spawn that must be cleared before the next archwalker appears.", "During the later stages, erratic arachnids replenish while the archwalker or Sigismond is engaged. Assign sustained add control.", "The third archwalker’s death makes Sigismond attackable. His periodic hate clears require active tank recovery."}}}},
  ["poair-stormrider-island"] = {overview = {"Break the stormrider formations and identify Pherlondien Clawpike among his copies."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear the twenty-seven designated island creatures to summon the Priest of Destruction and eight protected stormriders.", "The priest activates two stormriders at a time, beginning shortly after engagement and then every thirty seconds. Secure each pair as it becomes active.", "After the priest, defeat three sporadic stormriders to trigger the final formation.", "Pherlondien appears at a randomized position among four false copies. The cooldown state can instead produce a loathesome stormclaw.", "The final named opponent can clear hate; keep tanks ready while identifying and finishing the real target."}}}},
  ["poair-xegony-queen-of-air"] = {overview = {"Defeat Xegony’s six guard formations before attempting to finish the Queen of Air."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 99%, 85%, 70%, 55%, 40% and 25% health, Xegony activates one previously unused guard family and its named leader.", "The family order is randomized. Watch the active formation and assign tanks before pushing the next threshold.", "Guard leaders can clear their hate lists, and idle guards are called back into the fight. Maintain control rather than leaving loose adds unattended.", "At 13%, Xegony returns to 25% health if any of the six named leaders remain alive. Kill every leader before the final push.", "After an extended break from combat, the event resets. Victory produces the Essence of Air."}}}},
  ["ferubi-packmaster-skoiat-pizak"] = {overview = {"The Packmaster calls his Rav guards into combat and keeps bringing in more. Prepare tanks for four new Rav every 45 seconds rather than treating the opening guards as the whole encounter."}, roles = {{id = "tank", label = "Tanks", tips = {"Intercept the repeating Rav waves before they reach healers."}}, {id = "damage", label = "Damage dealers", tips = {"Clear new Rav promptly to prevent overlapping waves."}}}, phases = {}, abilities = {{name = "Rav reinforcements", summary = "Four Rav arrive every 45 seconds.", description = {"New arrivals attack random targets on the Packmaster's hate list. The Packmaster also calls existing guard types toward his current hate leader every 30 seconds."}, tags = {}, roles = {}}, {name = "Weapon matchups", summary = "Slashing and archery are favored over blunt attacks.", description = {"The Packmaster's script increases incoming slashing and archery skill damage and reduces incoming blunt skill damage."}, tags = {}, roles = {}}}, sections = {{title = "Recovery", paragraphs = {"One minute after the Packmaster leaves combat, the script removes both Rav guard types. Engaged Rav check their distance every five seconds and clear hate when more than 600 paces from the Packmaster."}, bullets = {}}}},
  ["ferubi-pxet-elite-ambushes"] = {overview = {"Ferubi tracks separate counters for the elite Blademaster, Spearmaster, Hammermaster and Brawler. Each elite appears when its own counter reaches 100 qualifying death signals.", "Only designated spawn points contribute. Killing an arbitrary creature of the same name does not necessarily advance a counter."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Independent elite counters", paragraphs = {"The counters persist between controller spawns. When an elite is triggered, its counter resets three seconds later; the other three counters continue independently."}, bullets = {}}}},
  ["ferubi-smith-rondo-weapon-master"] = {overview = {"Bring Rondo the four broken weapon components to summon Weapon Master Vtiink Vzaan and four apprentices. Rondo becomes vulnerable after the Weapon Master dies.", "Rondo transforms at 65% health. His attackable stage has a 45-minute timer, after which he returns home and becomes protected again."}, roles = {}, phases = {{label = "Weapon Master and apprentices", trigger = "Four-component turn-in", description = "The Weapon Master calls idle apprentices onto his target every six seconds. Apprentice replacement signals schedule their return after one minute."}, {label = "Smith Rondo", trigger = "Weapon Master defeated", description = "Rondo stands, loses his damage protection and begins his timed combat stage."}, {label = "Transformation", trigger = "65% health", description = "Rondo changes into a larger corrupted form. The script does not define a new damage ability at this threshold."}}, abilities = {}, sections = {{title = "Completion", paragraphs = {"Rondo's death creates his spectral memory for the follow-up. The component turn-in also records temporary presence credit for participating characters."}, bullets = {}}}},
  ["ferubi-smith-rondo-weapon-master-seasonal"] = {overview = {"Bring Rondo the four broken weapon components to summon Weapon Master Vtiink Vzaan and four apprentices. Rondo becomes vulnerable after the Weapon Master dies.", "Rondo transforms at 65% health. His attackable stage has a 45-minute timer, after which he returns home and becomes protected again."}, roles = {}, phases = {{label = "Weapon Master and apprentices", trigger = "Four-component turn-in", description = "The Weapon Master calls idle apprentices onto his target every six seconds. Apprentice replacement signals schedule their return after one minute."}, {label = "Smith Rondo", trigger = "Weapon Master defeated", description = "Rondo stands, loses his damage protection and begins his timed combat stage."}, {label = "Transformation", trigger = "65% health", description = "Rondo changes into a larger corrupted form. The script does not define a new damage ability at this threshold."}}, abilities = {}, sections = {{title = "Completion", paragraphs = {"Rondo's death creates his spectral memory for the follow-up. The component turn-in also records temporary presence credit for participating characters."}, bullets = {}}, {title = "Seasonal behavior", paragraphs = {"Theta Sigma offers the seasonal expedition. Rondo keeps the Weapon Master sequence and 65% transformation, with additional messages and a seasonal fragment appearing after his defeat. Leaving combat resets his appearance and the 65% trigger."}, bullets = {}}}},
  ["ferubi-zun-muram-votal"] = {overview = {"Votal brings both Pixtt guards into the fight, and the guards call one another and Votal when engaged. Plan for a linked pull instead of isolated enemies."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the fight south of the boundary and assign coverage for both guards."}}}, phases = {}, abilities = {{name = "Encounter boundary", summary = "Crossing north of Y -400 sends these enemies home.", description = {"The reviewed Votal and Pixtt scripts check the boundary every six seconds, return the NPC to its bind location and clear its hate list."}, tags = {}, roles = {}}}, sections = {{title = "Guard recovery", paragraphs = {"Votal creates the guards while idle. A 30-minute replacement timer begins on initial engagement; if he is still fighting when it expires, the replacement waits until combat ends."}, bullets = {}}}},
  ["ferubi-hexxt-pzik-shziaak"] = {overview = {"Hexxt Pzik Shziaak begins recurring ranged volleys below 45% health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for a change in the combat pattern when the boss reaches 45%.", "The volley check repeats every twenty seconds while that low-health behavior is active.", "Keep healing stable and maintain tank control through the final push."}}}},
  ["frontiermtns-goblin-king-dronan-event"] = {overview = {"Dronan's arrival begins a 30-minute contest. Goblin seekers spread through Frontier Mountains while announcements lead into the hiding stage.", "Eight minutes after the King spawns, four goblin hiders appear across the zone. One receives the quest prize; search the hiders before the contest ends."}, roles = {}, phases = {{label = "Seekers disperse", trigger = "King spawns", description = "Five seekers appear immediately, with further groups created on a 45-second timer."}, {label = "Find the hidden goblin", trigger = "Eight minutes after spawn", description = "Four hiders are created and one receives the prize."}, {label = "Contest ends", trigger = "Thirty minutes after spawn", description = "The King, seekers, hiders and associated named goblins are removed."}}, abilities = {}, sections = {}},
  ["fungusgrove-calling-beasties-murkin-groo-and-torgal"] = {overview = {"Murkin, Groo and Torgal run variants of the same cavern hunt. Give the chosen caller a drink to begin, then follow after the one-minute preparation period.", "Each wave brings three creatures. The caller pauses for five minutes after every five waves; larger drinks shorten the spacing within each set."}, roles = {}, phases = {}, abilities = {}, sections = {}},
  ["fungusgrove-draz-nurakk"] = {overview = {"When Draz gains a new enemy and his pet is present, he calls the pet onto his current hate leader after one second.", "Draz stops his one-hour despawn timer during combat. Leaving combat restarts the timer; when it expires, both Draz and his pet are removed."}, roles = {{id = "tank", label = "Tanks", tips = {"Pick up the pet as well as Draz at the start of combat."}}}, phases = {}, abilities = {}, sections = {}},
  ["gfaydark-seana-and-stefan-marsinger"] = {overview = {"The rogue quest notice, presented at the required quest stage, makes both twins attackable. Engaging either twin calls the other into combat.", "Seana gives a stone to her current hate leader ten seconds after combat starts. Five seconds later she checks her current hate leader again and sends that player to the Nexus if they hold the stone. She then waits 20 seconds before the next stone."}, roles = {}, phases = {}, abilities = {{name = "Stone and teleport", summary = "Seana can remove her current tank from the fight.", description = {"The recipient of the stone and the target of the later teleport are selected separately. A tank swap may change who is checked; have another tank ready to take over."}, tags = {}, roles = {}}}, sections = {}},
  ["unclaimed-dawn-house-5"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold the named near the middle while leaving both bellows accessible."}}, {id = "healer", label = "Healers", tips = {"Move out of the announced backdraft half-room."}}, {id = "damage", label = "Damage dealers", tips = {"One non-tank can use both bellows in sequence."}}, {id = "everyone", label = "Everyone", tips = {"Pressure resets every cycle; do not overlap interactions or remain in a backdraft."}}}, phases = {{label = "One breath for the house", trigger = "Every 35 seconds", description = "A visible pressure gauge starts at 3. Two floor bellows can each be used once during an 18-second cycle; each reduces pressure by one. A scheduled vent reduces the last point automatically. Interaction takes 2 seconds and may be performed sequentially by one non-tank."}, {label = "Backdraft", trigger = "At 50% HP and once 45 seconds later", description = "The boss announces the workshop side it will scorch in 12 seconds. The central aisle and opposite side remain safe, on the same arena floor."}}, abilities = {{name = "One breath for the house", summary = "Every 35 seconds", description = {"A visible pressure gauge starts at 3. Two floor bellows can each be used once during an 18-second cycle; each reduces pressure by one. A scheduled vent reduces the last point automatically. Interaction takes 2 seconds and may be performed sequentially by one non-tank.", "Success: Pressure reaches zero; the boss's 25% damage ward ends for 12 seconds.", "Failure: Each remaining point deals 125 fire damage to the group at venting, maximum 375. The gauge resets; no accumulated impossible state."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Backdraft", summary = "At 50% HP and once 45 seconds later", description = {"The boss announces the workshop side it will scorch in 12 seconds. The central aisle and opposite side remain safe, on the same arena floor.", "Success: Leave the named half-room before impact.", "Failure: 550 fire damage once to occupants of the named half; no knockback into walls or forced teleport."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for this expedition with three to six eligible characters of level 55 or higher. Have the leader check the guide's current entry requirements."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-house-3"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Lead the Harrower onto fertile soil, then leave the announced harvest radius."}}, {id = "healer", label = "Healers", tips = {"Move with the tank and expect one capped flower pulse if control fails."}}, {id = "damage", label = "Damage dealers", tips = {"Stop both flowers before their 18-second bloom."}}, {id = "everyone", label = "Everyone", tips = {"The named sprout identifies fertile soil; do not guess from color."}}}, phases = {{label = "What the roots drink", trigger = "Every 32 seconds", description = "Three sprouts appear on marked soil patches, two barren and one fertile. Lure the Harrower within 12 paces of the fertile sprout before its 10-second harvest; a named actor identifies the patch."}, {label = "Prune before bloom", trigger = "At 60% and 25% HP", description = "Two 3,500-HP nightflowers gain strength for 18 seconds. They can be mezzed, rooted, stunned or killed."}}, abilities = {{name = "What the roots drink", summary = "Every 32 seconds", description = {"Three sprouts appear on marked soil patches, two barren and one fertile. Lure the Harrower within 12 paces of the fertile sprout before its 10-second harvest; a named actor identifies the patch.", "Success: Roots bind the Harrower for 6 seconds and remove its 15% damage bonus for that cycle.", "Failure: It consumes the fertile sprout, heals 2% maximum HP once and deals 300 poison damage within 20 paces. Move away or recover."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Prune before bloom", summary = "At 60% and 25% HP", description = {"Two 3,500-HP nightflowers gain strength for 18 seconds. They can be mezzed, rooted, stunned or killed.", "Success: Each controlled or dead flower prevents its own bloom.", "Failure: Each uncontrolled surviving flower deals 175 poison damage to the group once; total failure damage is capped at 350."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for this expedition with three to six eligible characters of level 55 or higher. Have the leader check the guide's current entry requirements."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-house-4"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Face the frontal sweep away from the active standard."}}, {id = "healer", label = "Healers", tips = {"Keep the standard volunteer in range and watch the temporary melee bonus."}}, {id = "damage", label = "Damage dealers", tips = {"Handle the announced orderly before focusing its protected partner."}}, {id = "everyone", label = "Everyone", tips = {"A non-tank holds the named standard for four seconds."}}}, phases = {{label = "Hold the vacant place", trigger = "Every 30 seconds", description = "The marshal names one of three broad floor standards. One non-tank must stand within 8 paces of that standard for 4 continuous seconds within the 12-second window; the tank keeps the frontal sweep away. The same player cannot be assigned twice consecutively."}, {label = "Dismissed in order", trigger = "At 65% and 30% HP", description = "Two 4,000-HP orderlies arrive; the active standard names which one can be controlled first. The other remains attackable and can be tanked."}}, abilities = {{name = "Hold the vacant place", summary = "Every 30 seconds", description = {"The marshal names one of three broad floor standards. One non-tank must stand within 8 paces of that standard for 4 continuous seconds within the 12-second window; the tank keeps the frontal sweep away. The same player cannot be assigned twice consecutively.", "Success: The named standard absorbs the sweep and creates a 10-second opening.", "Failure: The group takes 300 magic damage; the boss gains a removable 15% melee bonus for 10 seconds."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Dismissed in order", summary = 