  ["unclaimed-dawn-house-2"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the Matron beside the jars without blocking the reader."}}, {id = "healer", label = "Healers", tips = {"Keep attendants controlled during a clue window."}}, {id = "damage", label = "Damage dealers", tips = {"Read the witness's detail and choose the jar that agrees."}}, {id = "everyone", label = "Everyone", tips = {"All clue information appears in text; wrong choices are recoverable."}}}, phases = {{label = "Comfort or truth", trigger = "At 75% and 40% HP", description = "Three visible memory jars speak short facts. Two repeat the same false comforting detail; the remaining jar agrees with a rescued witness. Interact with that jar within 20 seconds; all clues appear in text."}, {label = "Do not smash the witness", trigger = "Throughout combat", description = "A named witness and two hostile attendants remain visually distinct. Only attendants join combat; the witness cannot be damaged by player area spells."}}, abilities = {{name = "Comfort or truth", summary = "At 75% and 40% HP", description = {"Three visible memory jars speak short facts. Two repeat the same false comforting detail; the remaining jar agrees with a rescued witness. Interact with that jar within 20 seconds; all clues appear in text.", "Success: The ward breaks for 15 seconds and two controllable attendants withdraw.", "Failure: One wrong choice or timeout inflicts 300 magic damage on the group and gives the Matron a 1,500-HP rune. The correct clue is repeated; there is no random re-roll."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Do not smash the witness", summary = "Throughout combat", description = {"A named witness and two hostile attendants remain visually distinct. Only attendants join combat; the witness cannot be damaged by player area spells.", "Success: Keeping attendants controlled leaves room to read the clues.", "Failure: Living attendants heal the Matron 300 HP every 10 seconds, capped at two attendants."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for this expedition with three to six eligible characters of level 55 or higher. Have the leader check the guide's current entry requirements."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-house-1"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Turn the Porter away from the trunk route."}}, {id = "healer", label = "Healers", tips = {"Prepare for the marked player's 350-point failure hit."}}, {id = "damage", label = "Damage dealers", tips = {"Destroy one blocking trunk, not both; pick up luggage shades."}}, {id = "everyone", label = "Everyone", tips = {"The marked player uses the witness trunk, never their own trunk."}}}, phases = {{label = "The wrong luggage", trigger = "Every 28 seconds", description = "Two trunks open; one is named after the living marked player, the other after a released witness. The marked player has 12 seconds to stand within 10 paces of the witness trunk; no item is picked up."}, {label = "An overfull doorway", trigger = "At 65% and 30% HP", description = "Two trunks block a broad doorway. Destroy either within 18 seconds; both share a 4,000-HP budget and never block physical escape."}}, abilities = {{name = "The wrong luggage", summary = "Every 28 seconds", description = {"Two trunks open; one is named after the living marked player, the other after a released witness. The marked player has 12 seconds to stand within 10 paces of the witness trunk; no item is picked up.", "Success: The witness trunk shuts and the Porter loses its 20% damage ward for 12 seconds.", "Failure: The marked player takes 350 magic damage; one luggage shade appears, capped at two alive. No stun or permanent failure."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "An overfull doorway", summary = "At 65% and 30% HP", description = {"Two trunks block a broad doorway. Destroy either within 18 seconds; both share a 4,000-HP budget and never block physical escape.", "Success: A safe exit is announced; the Porter pauses melee for 4 seconds.", "Failure: The group takes 250 magic damage once and the trunks disappear. The fight continues."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for this expedition with three to six eligible characters of level 55 or higher. Have the leader check the guide's current entry requirements."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-house-6"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the Seneschal away from the tomb needed by the tethered volunteer."}}, {id = "healer", label = "Healers", tips = {"Prepare for a missed tether's 500-point single-target hit."}}, {id = "damage", label = "Damage dealers", tips = {"Kill the contradictory copy and control any memory leech."}}, {id = "everyone", label = "Everyone", tips = {"Read the complete witness detail before choosing a copy."}}}, phases = {{label = "Original and imitation", trigger = "At 75%, 45% and 20% HP", description = "Two identical-looking 4,000-HP copies appear with distinct names. A witness reads one of three explicit textual details of its original life. Attack the copy displaying the contradictory detail; both remain targetable."}, {label = "An inherited duty", trigger = "Every 27 seconds", description = "One non-tank receives a visible burden tether for 12 seconds. Stand within 12 paces of the named tomb to discharge it; the tomb is selected away from the active frontal arc."}}, abilities = {{name = "Original and imitation", summary = "At 75%, 45% and 20% HP", description = {"Two identical-looking 4,000-HP copies appear with distinct names. A witness reads one of three explicit textual details of its original life. Attack the copy displaying the contradictory detail; both remain targetable.", "Success: The false copy shatters; the other walks away and the boss loses 10% melee for 12 seconds.", "Failure: Killing the truthful copy creates a 2,000-HP memory leech. At the 20-second timeout both copies vanish and deal 250 magic damage to the group."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "An inherited duty", summary = "Every 27 seconds", description = {"One non-tank receives a visible burden tether for 12 seconds. Stand within 12 paces of the named tomb to discharge it; the tomb is selected away from the active frontal arc.", "Success: The tether fades harmlessly.", "Failure: The carrier takes 500 magic damage once, without a group-wide repeat."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for this expedition with three to six eligible characters of level 55 or higher. Have the leader check the guide's current entry requirements."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["grimling-captain-necins-raid"] = {overview = {"Show Necin the completed soldier's chest to receive a map, then return the map when the force is ready. Follow him and Cursah to the two camps.", "Both camps must be clear before counterattacks begin. After an initial 30-to-60-second delay, waves arrive every minute: four grimlings at the smaller camp and six at the larger camp."}, roles = {}, phases = {{label = "Capture both camps", trigger = "Necin begins the assault", description = "The event resets camp spawns. Clear both positions rather than relying on a pre-clear."}, {label = "Defend both leaders", trigger = "Both camps clear", description = "Protect Necin and Cursah while reinforcement waves arrive. Either leader's death fails the assault."}, {label = "Find the officer", trigger = "Officer warning", description = "The officer may appear at either camp. Waves stop when it arrives; kill it and return proof to Necin."}}, abilities = {}, sections = {}},
  ["grimling-final-grimling-war-general-staginars-raid"] = {overview = {"The final war follows General Staginar's progression and Cullin's march. Split your force between the Acrylia mines entrance and the northern fort, then clear both camps.", "Cullin, Shiktan, Kufur and Fhelik must all survive. The first counterattack begins 60 to 75 seconds after both camps are clear, followed by waves every minute. Ten grimlings head to the Acrylia entrance and five to the northern camp per ordinary wave."}, roles = {{id = "tank", label = "Tanks", tips = {"Assign tanks at both camps before the first wave."}}, {id = "healer", label = "Healers", tips = {"Keep healing coverage on all four veterans; losing any one fails the war."}}}, phases = {{label = "Secure both objectives", trigger = "Veterans launch the assault", description = "Clear both freshly repopulated camps."}, {label = "Protect all four veterans", trigger = "Both camps clear", description = "Defend both positions while the chance of a high-commander wave rises."}, {label = "High commander", trigger = "After the initial five waves", description = "The high commander can appear at the northern fort. Defeat it to end the defense and regroup the surviving veterans for the follow-up."}}, abilities = {}, sections = {}},
  ["grimling-scout-danarins-raid"] = {overview = {"Give Danarin the requested sphere, follow the scout and clear the occupied camp. The event refreshes the camp population when it starts, so clearing it beforehand does not skip this objective.", "After the camp is clear, reinforcements begin after a random 30 to 60 seconds and then arrive every 90 seconds. The officer can appear after the fifth wave, with the chance increasing as more waves pass."}, roles = {{id = "healer", label = "Healers", tips = {"Keep the scout alive throughout the assault."}}, {id = "damage", label = "Damage dealers", tips = {"Clear waves promptly and switch to the officer when it appears."}}}, phases = {{label = "Capture the camp", trigger = "Scout starts the assault", description = "Defeat the camp occupants while keeping the scout alive."}, {label = "Hold the camp", trigger = "Camp cleared", description = "Intercept the timed reinforcement waves. New waves stop when the officer appears."}, {label = "Defeat the officer", trigger = "Officer arrival", description = "Kill the officer and return its proof to the scout. Losing the scout fails the event."}}, abilities = {}, sections = {}},
  ["grimling-scout-derrins-raid"] = {overview = {"Give Derrin the requested sphere, follow the scout and clear the occupied camp. The event refreshes the camp population when it starts, so clearing it beforehand does not skip this objective.", "After the camp is clear, reinforcements begin after a random 30 to 60 seconds and then arrive every 60 seconds. The officer can appear after the fifth wave, with the chance increasing as more waves pass."}, roles = {{id = "healer", label = "Healers", tips = {"Keep the scout alive throughout the assault."}}, {id = "damage", label = "Damage dealers", tips = {"Clear waves promptly and switch to the officer when it appears."}}}, phases = {{label = "Capture the camp", trigger = "Scout starts the assault", description = "Defeat the camp occupants while keeping the scout alive."}, {label = "Hold the camp", trigger = "Camp cleared", description = "Intercept the timed reinforcement waves. New waves stop when the officer appears."}, {label = "Defeat the officer", trigger = "Officer arrival", description = "Kill the officer and return its proof to the scout. Losing the scout fails the event."}}, abilities = {}, sections = {}},
  ["grimling-scout-husmans-raid"] = {overview = {"Give Husman the requested sphere, follow the scout and clear the occupied camp. The event refreshes the camp population when it starts, so clearing it beforehand does not skip this objective.", "After the camp is clear, reinforcements begin after a random 30 to 60 seconds and then arrive every 120 seconds. The officer can appear after the fifth wave, with the chance increasing as more waves pass."}, roles = {{id = "healer", label = "Healers", tips = {"Keep the scout alive throughout the assault."}}, {id = "damage", label = "Damage dealers", tips = {"Clear waves promptly and switch to the officer when it appears."}}}, phases = {{label = "Capture the camp", trigger = "Scout starts the assault", description = "Defeat the camp occupants while keeping the scout alive."}, {label = "Hold the camp", trigger = "Camp cleared", description = "Intercept the timed reinforcement waves. New waves stop when the officer appears."}, {label = "Defeat the officer", trigger = "Officer arrival", description = "Kill the officer and return its proof to the scout. Losing the scout fails the event."}}, abilities = {}, sections = {}},
  ["grimling-veteran-vadrels-raid"] = {overview = {"Show Vadrel the medal from Necin's mission, then return the plans when ready. Follow the veterans and clear both camps after the assault resets their populations.", "Reinforcement waves begin after 30 to 60 seconds and then arrive every minute. Protect both veterans while watching for a grimling commander at either camp."}, roles = {}, phases = {{label = "Take both camps", trigger = "Plans returned", description = "Clear both camp areas to start the defense."}, {label = "Defeat the commander", trigger = "Commander appears", description = "Follow the veterans' warning to the correct camp. Kill the commander and return its proof to Vadrel. Either veteran's death fails the event."}}, abilities = {}, sections = {}},
  ["hohonora-alekson-garn-s-trial"] = {overview = {"Clear Alekson Garn’s three guarded rooms while protecting the maidens of Marr."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Speak with Alekson to enter the trial, then defeat its Custodian of Marr to start the room encounters.", "Each room begins with five enemies. Clear the room to bring out its named opponent: Advocent Joran, Halgoz Rell or Freegan Haun.", "Protect the maidens throughout the trial. Their loss can fail the event even if the attackers are being defeated.", "Defeat all three named opponents, then return to Alekson’s projection for trial credit."}}}},
  ["hohonora-rhaliq-trell-s-trial"] = {overview = {"Defend Rhaliq Trell’s villagers and defeat the twelve named attackers."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Speak to Rhaliq to reach the trial and kill its Custodian of Marr to begin.", "The event places seven villagers and twelve named opponents in the trial area. Secure the attackers before they overwhelm the protected villagers.", "The village gnome is a failure target. Keep defenders assigned to the villagers while the rest of the raid eliminates the named enemies.", "After all twelve named opponents die, speak with Rhaliq’s projection for completion credit."}}}},
  ["hohonora-rydda-dar-trydan-faye-s-trial"] = {overview = {"Trydan Faye’s trial culminates in a confrontation with Rydda’Dar."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat the trial’s Custodian of Marr to summon Rydda’Dar.", "Gather and prepare before triggering the dragon; its availability is limited by a two-hour timer.", "After Rydda’Dar falls, speak to Trydan Faye’s projection to complete the trial."}}}},
  ["harbingers-attendant-of-light"] = {overview = {"Defeating a dragorn sycophant can call the Attendant of Light and a group of discordling harassers."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The ritual begins with eight sycophants around the spawner. A sycophant death summons the Attendant if one is not already present.", "Four discordling harassers appear with the Attendant. Prepare to control the escort enemies when triggering the boss.", "The spawner tracks all eight sycophant deaths separately; killing all eight is not required by the Attendant’s spawn condition."}}}},
  ["harbingers-azibelle-spavin-and-glenfire-telzir"] = {overview = {"A druid epic ambush brings Azibelle Spavin and Glenfire Telzir into Harbinger’s Spire."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The hidden proximity trigger checks the druid’s quest state before summoning both opponents.", "Prepare for a two-enemy engagement rather than approaching the trigger alone. Establish separate control of the pair before focusing one down.", "The summoned enemies have a fifteen-minute cleanup window. Finish the encounter while both are available."}}}},
  ["harbingers-windrush"] = {overview = {"Windrush adds recurring spell attacks as the fight progresses."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 70% health, Windrush begins using Stunning Strike, repeating every twenty seconds after the initial cast.", "At 40% health, Mana Spectrum joins the rotation and repeats every fifteen seconds.", "Allow for increasing pressure on the tank and the group in the final stages. The encounter has a thirty-minute depop timer once engaged."}}}},
  ["hatesfury-broken-skull-armsmaster"] = {overview = {"Weaken the Broken Skull Armsmaster as part of the berserker’s preliminary epic trial."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 20% health, the Armsmaster exposes a weakness and begins checking the initiating fighter for War Cry.", "The special reaction requires a berserker at the correct preliminary epic stage with War Cry active. Coordinate the health push with that character.", "The weakness state resets after five minutes out of combat. Eligible berserkers receive quest advancement when the Armsmaster dies."}}}},
  ["hatesfury-captain-krasnok"] = {overview = {"Captain Krasnok appears with four Fists of Krasnok when the attendant receives the required quest hand-in."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Prepare the group before the hand-in to Attendant Mi-Ta; it creates the captain and his four defenders together.", "Assign control of the Fists while a tank establishes the captain. Clear supporting enemies to reduce the simultaneous pressure.", "Use the attendant’s passage NPCs to enter and leave the encounter area."}}}},
  ["hollowshade-hollowshade-moor-war"] = {overview = {"The owlbears, sonic wolves and grimlings battle for three camps across Hollowshade Moor."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"A camp boss’s death opens an attack against that camp. The defending race and ownership of the north, east and south camps determine the attackers.", "Attack waves have a fifteen-minute resolution window. Help a faction defeat the opposition to change control of a camp.", "Continue the war until one race holds all three camps. The resulting occupation changes the creatures available across the moor.", "Track camp ownership between attacks; the same boss kill can lead to different waves depending on the current war state."}}}},
  ["iceclad-general-bragmur-escort-coldain-shawl-finale"] = {overview = {"Escort General Bragmur across Iceclad and defend the Coldain shawl ceremony."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete the general’s required preparations before beginning the march. Follow Bragmur through his route rather than racing ahead.", "Wolves and giants ambush the escort at fixed waypoints. Pick them up quickly so they do not kill the general.", "The later attacks include Kvarid and Vjorik. Hold a reserve for these named attackers while keeping the escort safe.", "Remain through the final ceremony and follow the general’s dialogue to complete the quest sequence."}}}},
  ["iceclad-noble-oldencamp-and-the-necromancer-delegation"] = {overview = {"Noble Oldencamp arrives with an armed delegation after Vas Thorel’s quest exchange."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Prepare for the full delegation before the trigger: Oldencamp arrives with Amilia Verisue, Xeegarn, Puella Opalis, Locis Vera and six additional escorts or warriors.", "Separate the supporting opponents from the principal target so the group can control the large initial pull.", "The delegation has a one-hour cleanup timer. Complete the required kills and quest steps before the visit ends."}}}},
  ["ikkinz-chambers-of-destruction-keeper-of-the-altar"] = {overview = {"Break the altar’s defenses and confront a Keeper that combines throws, short-lived attackers and class-sensitive adherents."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"During the approach, respect the altar defenders’ room boundaries and resolve the adherents’ class clues before delivering their finishing blows.", "The Keeper repeatedly creates assailants, which exhaust themselves after fifteen seconds, and calls up to five adherents over the encounter.", "Throw hits several hate-list targets and brings distant players back toward the Keeper. Recover positioning promptly; distance is not a reliable escape.", "Earthen Shrapnel and Bury continue alongside the add cycle. Assign add tanks so the main tank can stay on the Keeper.", "At 50% and 10% health, the Keeper enters a five-second rampage burst. Prepare healing before pushing either threshold.", "After three minutes out of combat, the Keeper heals and clears its summoned enemies."}}}},
  ["ikkinz-chambers-of-glorification"] = {overview = {"Weaken the stone guardians through their supporting creatures, then handle each guardian split."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Visionary of Glory uses rampage between 50% and 40% health and again below 10%. Keep the fight in its chamber.", "Glorified supporting creatures strengthen the guardian’s health, regeneration or damage. Clearing them reduces the pressure during the guardian sequence.", "The Guardian of Glorification splits into smaller forms. Its intermediate forms split again at 50% health, so prepare to tank additional targets rather than assuming a nearly defeated target is the end.", "The stone forms can throw players, launch magical attacks and return players who leave their permitted area. Regroup inside the encounter space after displacement."}}}},
  ["ikkinz-chambers-of-righteousness"] = {overview = {"Clear the Chambers of Righteousness and defeat its priests, defenders and final custodian."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Priests and the Custodian enter rampage at 50% health, stop at 40%, and resume at 10%. Prepare healing before each health transition.", "The Custodian clears its hate list every forty-five seconds. Tanks should be ready to regain its attention when the weight-shifting emote appears.", "Keep each guardian within its assigned chamber. Crossing the scripted boundaries causes a return home and clears hate.", "Complete the required defender kills to open the way through the chamber and finish with the Custodian."}}}},
  ["ikkinz-chambers-of-singular-might"] = {overview = {"Reach and defeat the Pixtt Annihilator in the Chambers of Singular Might."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Follow the accessible passage through the first group trial. The later sealed doors are not part of the route for Singular Might.", "Defeat the Pixtt Annihilator to complete the named encounter. Its death grants a seven-hour replay lockout to the expedition."}}}},
  ["ikkinz-chambers-of-the-tri-fates"] = {overview = {"Defeat all three Tri-Fate hunters before their replacements undo your progress."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each hunter’s death begins a twelve-minute replacement timer and starts summoning Pixtt Annuller reinforcements after a random delay.", "Hunter replacement timers pause while a hunter is engaged and resume when combat ends. Move promptly between targets rather than taking a long break after a kill.", "Control the annullers while finishing the remaining hunters. All three hunters must be absent together to complete the trial.", "Completion locks the expedition to new entrants and grants the trial’s replay lockout."}}}},
  ["ikkinz-chambers-of-transcendence"] = {overview = {"Face the Transcendent Acolytes, follow the Guardian and solve the sentinels’ class requirements to release Vrex Xalkak Nixki."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Transcendent Acolytes briefly rampage at 50% and 10% health. Stay inside their chamber to avoid a full heal and reset.", "The Guardian of Transcendence retreats at 90%, 75% and 50% health, opening doors along its route. Defeat its last manifestation to reveal Vrex and his four sentinels.", "A sentinel reveals a class clue at 10%. Let a player of the required class deliver the killing blow; an incorrect finisher causes the sentinel to return.", "Vrex remains protected during the sentinel sequence and can still disrupt nearby players. Complete the sentinels and marauder progression to activate him.", "While not engaged, Vrex alternates between very high and low health. Coordinate the pull around this change, then maintain combat.", "At 4% health, Vrex enters a final five-second rampage burst."}}}},
  ["ikkinz-chambers-of-twin-struggles"] = {overview = {"Free the constrained servitors to weaken the two Malevolent Priests, then defeat the priests together."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each servitor death removes ten percent of a priest’s maximum health. Destroy all the constrained servitors to remove the priests’ protection.", "The priests repeatedly attack nearby players with Malevolent Assault, Coordinated Strike or Malevolent Vex. Prepare for pressure before they become directly attackable.", "Servitors can clear their hate list shortly after combat begins. Tanks should re-establish control rather than relying only on the initial pull.", "Keep the priests inside their narrow encounter area. Both must die to complete the trial and close the expedition."}}}},
  ["inktuta-kelekdrix-herald-of-trushar"] = {overview = {"Clear Kelekdrix’s watchers and ushers to break her rocky protection, then maintain control as reinforcements return."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Soon after engagement, Kelekdrix becomes protected and calls four minions. Defeat every watcher and usher to make her attackable.", "Reinforcements return on a variable timer. Pick them up and clear them while keeping the raid ready for the boss’s exposed windows.", "When active, Kelekdrix can banish her highest-hate player. Have another tank ready to take over.", "Her defeat unlocks the lower reaches of Inktu’ta and advances the expedition."}}}},
  ["inktuta-noqufiel-true-and-mirror-images"] = {overview = {"Identify Noqufiel’s true image, halt attacks on the revealed mirror and repeat the deception cycle until the true image falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Both images initially use the name Noqufiel. Removing five percent health reveals an image’s identity.", "Attack the True Image once revealed. Stop all attacks, pets and damage-over-time effects on the Mirror Image; after a two-second grace period, further health loss can detonate it.", "Another five-percent push on the true image resets the pair to hidden forms. Re-identify the target at each cycle instead of assuming the same visible position is safe.", "Hidden forms banish their highest-hate player and can spawn cursebearers. Keep backup tanks ready and avoid dragging either image beyond the room boundary.", "Out-of-combat regeneration can reverse progress to an earlier stage. Maintain controlled pressure on the correct image."}}}},
  ["inktuta-the-cursecallers"] = {overview = {"Defeat six Cursecallers while managing the cursebearers sustained by each caller."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The event creates an initial set of six cursebearers after fifteen seconds.", "Every fifteen seconds, the controller replaces a missing cursebearer if its corresponding Cursecaller still lives.", "Focus the Cursecallers to permanently stop their paired reinforcements. Once a caller is dead, its remaining cursebearer is removed.", "Defeating all six callers clears the remaining bearers and unlocks the next part of the expedition."}}}},
  ["inktuta-the-exiles-stonemite-trial"] = {overview = {"Coordinate the four exiles’ responses within one short window to pass the Stonemite trial."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Assign a player to each exile and determine the required response from that exile’s dialogue before starting the coordinated attempt.", "The first correct response starts a twenty-second window. All four exile responses must reach the controller before it expires.", "If the window closes without all four responses, the exiles summon stonemites and the response state resets. Clear the failure wave before trying again.", "A successful set removes the exiles, opens the next door and advances the expedition."}}}},
  ["jaggedpine-dire-kodiak-forest-dragon-transformation"] = {overview = {"A dire kodiak reveals a forest dragon when driven below 80% health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Lower the dire kodiak to the transformation threshold with the group ready for a replacement target.", "The kodiak disappears and the forest dragon appears at its location. Re-establish the tank’s target and hate immediately.", "If the dragon is already present, the transformation is postponed instead of creating another copy."}}}},
  ["kael-fabled-king-tormax"] = {overview = {"Fabled King Tormax calls his royal guard into the battle."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The fabled expedition replaces the ordinary Tormax encounter. Prepare for Kyenka, Yetarr, Irrek and Velden to assist their king.", "Tormax directs surviving guards at his current top-hate target on engagement and again every five minutes. Control or defeat the guards to keep them from rejoining unattended.", "His defeat records the fabled encounter’s expedition lockout."}}}},
  ["kael-fabled-statue-idol-and-avatar-of-war"] = {overview = {"Fight through the Fabled Statue and Idol to summon the Fabled Avatar of War."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Engaging the Statue calls the Armor of Zek for assistance. Clear or control the defenders while finishing the Statue.", "The Statue’s death summons the Idol; the Idol’s death summons the Avatar of War.", "The Avatar has a one-hour availability timer that pauses while it is engaged and resumes outside combat.", "Each defeated stage records its own fabled lockout, allowing expedition state to restore the appropriate remaining stage."}}}},
  ["kael-kael-armor-plate-cycle"] = {overview = {"Provoke Doldigun to begin Kael’s successive giant challenge."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Near the hidden trigger, say: The dain shall be slain for the peace we must obtain. This brings out Doldigun Steinwielder.", "Engage Doldigun or complete his quest hand-in to begin the cycle. He calls two giants and leaves.", "Defeating the cycle’s giants brings further opponents; remain in the event area and prepare for the next arrival after each kill.", "Doldigun departs after ten minutes if the event is not started."}}}},
  ["kael-king-tormax"] = {overview = {"King Tormax relies on his surviving royal guards throughout the fight."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Kyenka, Yetarr, Irrek and Velden are directed onto Tormax’s top-hate target as combat begins.", "Every five minutes, Tormax calls the surviving guards back into the battle. Do not leave uncontrolled guards idle elsewhere.", "Assign guard tanks or clear the guards before committing the raid to Tormax."}}}},
  ["kael-statue-idol-and-avatar-of-war"] = {overview = {"Defeat the Statue and Idol of Rallos Zek to call forth the Avatar of War."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Statue’s death summons the Idol. Prepare the raid for the next stage before finishing the current target.", "Defeating the Idol summons the Avatar of War in the temple.", "The Avatar’s one-hour depop timer limits how long the raid can leave the final encounter waiting."}}}},
  ["katta-rakshasa-skull-ritual"] = {overview = {"Roshawna’s skull ritual summons a courier and a group of reanimated Vah Shir."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete the ritual hand-in only when your group is prepared. The sequence creates a courier and eight reanimated Vah Shir.", "Control the supporting undead while completing the ritual’s combat objective.", "Return to the quest giver after the fight to finish the requested collection and hand-in steps."}}}},
}
